void unit_test_update_non_head_node_only_ct(void) {
    // Setup: Build a linked list with at least two nodes.
    // We need the target node to NOT be the head, and we want to update only CT (non-zero),
    // while WT and TAT are zero (so those branches are skipped).
    int ids[] = {1, 2, 3};
    int ats[] = {0, 1, 2};
    int bts[] = {5, 4, 3};
    int priorities[] = {1, 2, 3};
    int size = 3;
    struct node *root = helper_build_process_queue(ids, ats, bts, priorities, size);
    TEST_ASSERT_NOT_NULL(root);

    // Verify initial CT values are zero (as set by insert)
    struct node *ptr = root;
    while (ptr != NULL) {
        TEST_ASSERT_EQUAL_INT(0, ptr->CT);
        ptr = ptr->next;
